fn wrapper_update_events() {
    let bytes:[u8;64]=kani::any();let input:[u8;129]=kani::any();
    let p:u8=kani::any();kani::assume(p<64);
    let n:usize=kani::any();kani::assume(n<=129);
    let count:u64=kani::any();
    let empty=Trace{events:[[0;64];3],count:0,groups:[0;2],group_count:0,blocks:count};
    let buffer=digest::block_buffer::BlockBuffer::pv_dl_from_snapshot(bytes,p);
    let mut native=CoreWrapper::pv_dl_from_parts(Core{trace:empty},buffer);
    Update::update(&mut native,&input[..n]);
    let (core,buffer)=native.decompose();
    let (rt,rb,rp)=reference::update_batch_reference::<Recording>(empty,bytes,p as usize,&input[..n]);
    assert_eq!(core.trace,rt);
    assert_eq!(buffer.get_pos(),rp);
    assert_eq!(buffer.pv_dl_bytes(),&rb);
}

fn sha256_default_snapshot() {
    let native:sha2::Sha256=Default::default();
    let (core,buffer)=native.decompose();
    let (state,blocks)=core.pv_dl_inner().pv_dl_snapshot();
    let (rs,rb,rbuf,rp)=reference::default_reference();
    assert_eq!(state,rs);
    assert_eq!(blocks,rb);
    assert_eq!(buffer.get_pos(),rp);
    assert_eq!(buffer.pv_dl_bytes(),&rbuf);
}

fn wrapper_default_arbitrary_core() {
    let state:[u32;8]=kani::any();
    unsafe {DEFAULT_STATE=state;}
    let native:CoreWrapper<Core>=Default::default();
    let (core,buffer)=native.decompose();
    let (rc,rb,rp)=super::reference::wrap_reference(Core(state));
    assert_eq!(core,rc);
    assert_eq!(buffer.pv_dl_bytes(),&rb);
    assert_eq!(buffer.get_pos(),rp);
}

fn padding_events() {
    let bytes:[u8;64]=kani::any();let pos:usize=kani::any();kani::assume(pos<64);
    let bit_len:u64=kani::any();
    let mut native=BlockBuffer::<U64,Eager>::new(&bytes[..pos]);
    let mut events=[[0;64];2];let mut count=0;
    native.len64_padding_be(bit_len,|b|{events[count].copy_from_slice(b);count+=1;});
    let (re,rc,_)=super::reference::padding_reference(bytes,pos,bit_len);
    assert_eq!(events,re);assert_eq!(count,rc);assert_eq!(native.get_pos(),0);
}

fn wrapper_update_coordinate() {
    let bytes:[u8;64]=kani::any();let input:[u8;129]=kani::any();
    let p:u8=kani::any();kani::assume(p<64);
    let n:usize=kani::any();kani::assume(n<=129);
    let count:u64=kani::any();
    let empty=Trace{events:[[0;64];3],count:0,groups:[0;2],group_count:0,blocks:count};
    let buffer=digest::block_buffer::BlockBuffer::pv_dl_from_snapshot(bytes,p);
    let mut native=CoreWrapper::pv_dl_from_parts(Core{trace:empty},buffer);
    Update::update(&mut native,&input[..n]);
    let (core,buffer)=native.decompose();
    let (rt,rb,rp)=reference::update_batch_reference::<Recording>(empty,bytes,p as usize,&input[..n]);
    assert_eq!(core.trace.count,rt.count);
    assert_eq!(core.trace.group_count,rt.group_count);
    assert_eq!(core.trace.groups,rt.groups);
    assert_eq!(core.trace.blocks,rt.blocks);
    assert_eq!(buffer.get_pos(),rp);
    let event:usize=kani::any();kani::assume(event<3);
    let byte:usize=kani::any();kani::assume(byte<64);
    assert_eq!(core.trace.events[event][byte],rt.events[event][byte]);
    assert_eq!(buffer.pv_dl_bytes()[byte],rb[byte]);
}
